   887→// apps/desktop/src/navigation/navigate.ts
   888→import { registry } from "./route-registry";
   889→import { buildColdStartBreadcrumb, deriveAncestorsFromPrefix, buildBreadcrumbItem, type NavigateHeaders, type BreadcrumbStackItem } from "./breadcrumb-builder";
   890→import type { RouteMatch } from "./route-compiler";
   891→
   892→export type NavigateMethod = "push" | "replace" | "reset";
   893→
   894→/**
   895→ * Build the leaf BreadcrumbStackItem for a given URL.
   896→ * Used by the navigate function and can be used standalone.
   897→ */
   898→export function buildNavigateLeaf(url: string, headers?: NavigateHeaders): BreadcrumbStackItem {
   899→  const match = registry.match(url);
   900→  const fallbackLabel = url.split("/").filter(Boolean).pop() ?? url;
   901→
   902→  return {
   903→    id: headers?.id ?? url,
   904→    label: headers?.label ?? match?.title ?? fallbackLabel,
   905→    icon: headers?.icon ?? match?.icon,
   906→    pattern: match?.pattern,
   907→    href: url,
   908→    sourceNodeId: headers?.sourceNodeId,
   909→    parentNodeId: headers?.parentNodeId,
   910→    meta: headers?.meta,
   911→  };
   912→}
   913→
   914→/**
   915→ * Unified navigate function — the primary API for all navigation.
   916→ *
   917→ * Called from use-desktop-routing hooks. Dispatches to the appropriate
   918→ * tab store action based on method.
   919→ *
   920→ * @param method - "push" appends leaf to stack, "replace" replaces top, "reset" rebuilds from cold-start
   921→ * @param url - The target URL (built via registry.build)
   922→ * @param headers - Optional overrides for the breadcrumb leaf (label, icon, meta, etc.)
   923→ * @param tabStore - Tab store actions (injected by hook to avoid module-level coupling)
   924→ */
   925→export function navigate(
   926→  method: NavigateMethod,
   927→  url: string,
   928→  headers: NavigateHeaders | undefined,
   929→  tabStore: {
   930→    activeTabId: string;
   931→    pushNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
   932→    replaceNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
   933→    resetNavigation: (tabId: string, url: string, stack: BreadcrumbStackItem[]) => void;
   934→  },
   935→): void {
   936→  const { activeTabId } = tabStore;
   937→  const leaf = buildNavigateLeaf(url, headers);
   938→
   939→  switch (method) {
   940→    case "push":
   941→      tabStore.pushNavigation(activeTabId, url, leaf);
   942→      break;
   943→    case "replace":
   944→      tabStore.replaceNavigation(activeTabId, url, leaf);
   945→      break;
   946→    case "reset": {
   947→      const stack = buildColdStartBreadcrumb(url, headers);
   948→      tabStore.resetNavigation(activeTabId, url, stack);
   949→      break;
   950→    }
   951→  }
   952→}
   953→
   954→/**
   955→ * Breadcrumb click handler — pops to the Nth breadcrumb item.
   956→ * Deduplicates: if a matching entry already exists in backward history, jumps there.
   957→ * Otherwise inserts before current position.
   958→ */
   959→export function popToBreadcrumb(
   960→  index: number,
   961→  tabStore: {
   962→    activeTabId: string;
   963→    getCurrentState: (tabId: string) => { breadcrumbStack: BreadcrumbStackItem[]; url: string } | null;
   964→    findHistoryEntryByUrl: (tabId: string, url: string) => number;
   965→    jumpToHistory: (tabId: string, historyIndex: number) => void;
   966→    insertHistoryBeforeCurrent: (tabId: string, state: { url: string; breadcrumbStack: BreadcrumbStackItem[] }) => void;
   967→  },
   968→): void {
   969→  const { activeTabId } = tabStore;
   970→  const current = tabStore.getCurrentState(activeTabId);
   971→  if (!current) return;
   972→
   973→  const targetItem = current.breadcrumbStack[index];
   974→  if (!targetItem?.href) return;
   975→
   976→  // Dedup: check if backward history already has this URL
   977→  const existingIndex = tabStore.findHistoryEntryByUrl(activeTabId, targetItem.href);
   978→  if (existingIndex >= 0) {
   979→    tabStore.jumpToHistory(activeTabId, existingIndex);
   980→    return;
   981→  }
   982→
   983→  // No match → insert new state before current (preserves forward history)
   984→  tabStore.insertHistoryBeforeCurrent(activeTabId, {
   985→    url: targetItem.href,
   986→    breadcrumbStack: current.breadcrumbStack.slice(0, index + 1),
   987→  });
   988→}
   989→
   990→/**
   991→ * Check whether the current breadcrumb stack is a valid prefix of the target match.
   992→ * Used by Tab-Router Bridge for smart push vs cold-start reset decision.
   993→ */
   994→export function isStackPrefixOf(stack: BreadcrumbStackItem[], match: RouteMatch): boolean {
   995→  if (stack.length === 0) return false;
   996→  const topPattern = stack[stack.length - 1]?.pattern;
   997→  if (!topPattern) return false;
   998→  const ancestors = deriveAncestorsFromPrefix(match.pattern);
   999→  return ancestors.includes(topPattern);
  1000→}
  1001→
  1002→// Re-exports for convenience
  1003→export { buildColdStartBreadcrumb, buildBreadcrumbItem, deriveAncestorsFromPrefix, type NavigateHeaders, type BreadcrumbStackItem } from "./breadcrumb-builder";
  1004→export { registry } from "./route-registry";
  1005→```
