    52→  const activeTab = useMemo(
    53→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    54→    [activeTabRaw]
    55→  );
    56→
    57→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    58→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    59→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    60→  const currentNavigationState = activeTabId
    61→    ? getCurrentNavigationState(activeTabId)
    62→    : null;
    63→
    64→  return useMemo(
